# ENHANCED_V1: Test that the ChatAgent shim can be imported
import importlib

def test_chat_agent_import():
    module = importlib.import_module("camel.agents.chat_agent")
    assert hasattr(module, "ChatAgent"), "ChatAgent not exported"
    from camel.agents.chat_agent import ChatAgent
    try:
        ChatAgent()
    except NotImplementedError:
        pass
    else:
        # If a real implementation exists, it may not raise; that's acceptable.
        pass

